package org.apache.commons.lang.text;

import junit.framework.TestCase;

public class AgentBRT_Lang_59_raw_diff_Test extends TestCase {

    public void testReproduceBug() {
        StrBuilder strBuilder = new StrBuilder();
        String input = "1234567890";
        int width = 5;
        strBuilder.appendFixedWidthPadRight(input, width, '-');
        // Expect only the first 'width' characters to be appended
        assertEquals("12345", strBuilder.toString());
    }
}

